"""Generate client casefold/category tables from the native Python Unicode version."""

import json
import sys
import unicodedata
from pathlib import Path

root = Path(__file__).resolve().parents[3]
folds = {
    chr(value): chr(value).casefold()
    for value in range(sys.maxunicode + 1)
    if chr(value).casefold() != chr(value)
}
target = root / "mfes/apps/console/app/lib/serial-casefold.ts"
target.write_text(
    "// Generated by docs/testing/serial-fixes/generate_casefold.py.\n"
    f"// Native Unicode {unicodedata.unidata_version}; do not substitute locale lowercase.\n"
    "export const serialCasefold: Readonly<Record<string, string>> = "
    + json.dumps(folds, ensure_ascii=True, separators=(",", ":"))
    + ";\n",
    encoding="utf-8",
)
ranges: list[list[int]] = []
for value in range(sys.maxunicode + 1):
    if unicodedata.category(chr(value)).startswith("C"):
        if ranges and ranges[-1][1] == value - 1:
            ranges[-1][1] = value
        else:
            ranges.append([value, value])
with target.open("a", encoding="utf-8") as output:
    output.write(
        "export const serialNonprintable: readonly (readonly [number, number])[] = "
        + json.dumps(ranges, separators=(",", ":"))
        + ";\n"
    )
